type Brand = keyof typeof ART;
type Glyph = "server" | "terminal" | "share";

/** Each catalog provider's mark. The same brand may stand for two providers
 *  (Hetzner's object storage and Storage Box), never the other way round. */
const MARK_OF: Record<string, Brand | Glyph | "bombvault"> = {
  b2: "b2",
  s3: "aws",
  r2: "cloudflare",
  wasabi: "wasabi",
  "hetzner-os": "hetzner",
  storj: "storj",
  idrive: "idrive",
  scaleway: "scaleway",
  ovh: "ovh",
  digitalocean: "digitalocean",
  ionos: "ionos",
  contabo: "contabo",
  exoscale: "exoscale",
  vultr: "vultr",
  gcs: "googlecloud",
  azure: "azure",
  storagebox: "hetzner",
  minio: "minio",
  seaweedfs: "seaweedfs",
  garage: "garage",
  ceph: "ceph",
  juicefs: "server",
  rustfs: "rustfs",
  versitygw: "versity",
  "s3-other": "server",
  nextcloud: "nextcloud",
  owncloud: "owncloud",
  opencloud: "opencloud",
  "rest-server": "server",
  sftp: "terminal",
  bombvault: "bombvault",
  rclone: "rclone",
  synology: "synology",
  qnap: "qnap",
  truenas: "truenas",
  "unraid-other": "unraid",
  share: "share",
  "unraid-folder": "unraid",
};

/**
 * The colour each brand's tile lights up in under the pointer ("Brand tiles"
 * in GlimStone) and the ink on it: the brand's own colour, and white wherever
 * white keeps 2.5:1 on it, #161616 below that. OpenCloud keeps its own pair.
 */
const TILES: Record<Brand, { color: string; ink: string }> = {
  b2: { color: "#e21e29", ink: "#ffffff" },
  aws: { color: "#252f3e", ink: "#ffffff" },
  cloudflare: { color: "#f38020", ink: "#ffffff" },
  wasabi: { color: "#01cd3e", ink: "#161616" },
  hetzner: { color: "#d50c2d", ink: "#ffffff" },
  storj: { color: "#0052ff", ink: "#ffffff" },
  idrive: { color: "#1372ba", ink: "#ffffff" },
  scaleway: { color: "#4f0599", ink: "#ffffff" },
  ovh: { color: "#123f6d", ink: "#ffffff" },
  digitalocean: { color: "#0080ff", ink: "#ffffff" },
  ionos: { color: "#003d8f", ink: "#ffffff" },
  contabo: { color: "#00aaeb", ink: "#ffffff" },
  exoscale: { color: "#da291c", ink: "#ffffff" },
  vultr: { color: "#007bfc", ink: "#ffffff" },
  googlecloud: { color: "#4285f4", ink: "#ffffff" },
  azure: { color: "#0072c6", ink: "#ffffff" },
  minio: { color: "#c72e49", ink: "#ffffff" },
  seaweedfs: { color: "#0162bf", ink: "#ffffff" },
  garage: { color: "#ff9329", ink: "#161616" },
  ceph: { color: "#f0424d", ink: "#ffffff" },
  rustfs: { color: "#0196d0", ink: "#ffffff" },
  versity: { color: "#191b2a", ink: "#ffffff" },
  nextcloud: { color: "#0082c9", ink: "#ffffff" },
  owncloud: { color: "#041e42", ink: "#ffffff" },
  opencloud: { color: "#20434f", ink: "#e2baff" },
  rclone: { color: "#3f79ad", ink: "#ffffff" },
  synology: { color: "#b5b5b6", ink: "#161616" },
  qnap: { color: "#0c2e82", ink: "#ffffff" },
  truenas: { color: "#0095d5", ink: "#ffffff" },
  unraid: { color: "#f15a2c", ink: "#ffffff" },
};

/** placeTile is the lit tile of a provider's brand, undefined for one without a mark of its own. */
export function placeTile(provider: string): { color: string; ink: string } | undefined {
  const mark = Object.hasOwn(MARK_OF, provider) ? MARK_OF[provider] : undefined;
  return mark && Object.hasOwn(TILES, mark) ? TILES[mark as Brand] : undefined;
}

/** A console: a screen with a prompt cut out. */
function GlyphTerminal() {
  return (
    <svg width="16" height="16" viewBox="0 0 14 14" fill="currentColor" className="shrink-0" aria-hidden="true">
      <path
        fillRule="evenodd"
        d="M1.5 1h11A1.5 1.5 0 0 1 14 2.5v9a1.5 1.5 0 0 1 -1.5 1.5h-11A1.5 1.5 0 0 1 0 11.5v-9A1.5 1.5 0 0 1 1.5 1ZM3.2 4.35 5.85 7 3.2 9.65l1 1L7.85 7 4.2 3.35ZM8 9.3v1.35h3.5V9.3Z"
      />
    </svg>
  );
}

/** A folder on the network: a folder on a line with a node. */
function GlyphShare() {
  return (
    <svg width="16" height="16" viewBox="0 0 14 14" fill="currentColor" className="shrink-0" aria-hidden="true">
      <path d="M0 2.5A1.5 1.5 0 0 1 1.5 1h3.379a1.5 1.5 0 0 1 1.06 0.44L7 2.5h5.5A1.5 1.5 0 0 1 14 4v3.5A1.5 1.5 0 0 1 12.5 9h-11A1.5 1.5 0 0 1 0 7.5ZM6.25 9h1.5v2h-1.5ZM0.75 11h12.5a0.75 0.75 0 0 1 0 1.5H0.75a0.75 0.75 0 0 1 0 -1.5ZM5 10.5h4V13H5Z" />
    </svg>
  );
}

const GLYPHS: Record<Glyph, () => ReactNode> = {
  server: () => <IconLocal />,
  terminal: () => <GlyphTerminal />,
  share: () => <GlyphShare />,
};

/**
 * PlaceMark is a provider's mark, `size` pixels square. `onFill` is for a mark
 * on an accent fill: a brand colour there is an unpredictable contrast, so the
 * mark takes the fill's ink. A provider this version does not know gets the
 * server glyph rather than someone else's brand.
 */
export function PlaceMark({ provider, size = 16, onFill = false }: { provider: string; size?: number; onFill?: boolean }) {
  const scope = useId().replace(/[^\w-]/g, "");
  const mark = Object.hasOwn(MARK_OF, provider) ? MARK_OF[provider] : "server";
  const box = { width: size, height: size };
  if (mark === "bombvault") {
    // Our own logo, in the same two files as the sidebar's.
    return (
      <span className="glim-place-logo inline-flex shrink-0" style={box} aria-hidden="true">
        <img src="/logo.svg" alt="" draggable={false} className="h-full w-full object-contain dark:hidden" />
        <img src="/logo-light.svg" alt="" draggable={false} className="hidden h-full w-full object-contain dark:block" />
      </span>
    );
  }
  if (mark === "server" || mark === "terminal" || mark === "share") {
    return (
      <span className="inline-flex shrink-0 [&>svg]:h-full [&>svg]:w-full" style={box} aria-hidden="true" data-glyph={mark}>
        {GLYPHS[mark]()}
      </span>
    );
  }
  const art: Art = ART[mark];
  return (
    <svg
      width={size}
      height={size}
      viewBox={art.box}
      className={`glim-place-mark shrink-0${onFill ? " glim-mark-on-fill" : ""}`}
      aria-hidden="true"
      data-mark={mark}
    >
      {art.draw((n) => `pm${scope}${mark}${n}`)}
    </svg>
  );
}
